{
  "milestones": [
    {
      "id": "m1",
      "title": "Add invalidate_all to memoize",
      "requests": [
        "R1"
      ],
      "requirement": "The @memoize decorator should expose an .invalidate_all method on the wrapper that clears its internal memory cache.",
      "observable": "@memoize decorated function has .memory attribute; calling .invalidate_all() makes .memory empty; subsequent calls recompute.",
      "public_names": [
        "memoize"
      ],
      "requires": [],
      "why_requires": "memoize is a standalone function in calc.py. Adding .invalidate_all requires modifying the wrapper closure inside memoize, which is a prerequisite for any unified invalidation interface."
    },
    {
      "id": "m2",
      "title": "Add skip and invalidate to memoize",
      "requests": [
        "R1"
      ],
      "requirement": "The @memoize decorator should support skipping memoization via a SkipMemoization exception (already present but needs to be part of the public API contract) and expose an .invalidate method to remove specific keys.",
      "observable": "raising memoize.skip(value) returns value without caching; @memoize decorated function has .invalidate(key) method that removes key from .memory.",
      "public_names": [
        "memoize",
        "SkipMemoization"
      ],
      "requires": [
        "m1"
      ],
      "why_requires": "This milestone extends the same memoize wrapper structure established in m1. It adds the .invalidate method and ensures SkipMemoization behavior is consistent with the new public API surface being built for unification."
    },
    {
      "id": "m3",
      "title": "Unify cache invalidation API",
      "requests": [
        "R1"
      ],
      "requirement": "The @cache decorator should expose .skip and .invalidate methods on the wrapper to match the API added to @memoize, ensuring both decorators have consistent invalidation interfaces.",
      "observable": "@cache decorated function has .skip attribute (or raises appropriate error if not supported, but request implies unification); @cache decorated function has .invalidate(key) method; @cache decorated function has .invalidate_all() method (existing).",
      "public_names": [
        "cache"
      ],
      "requires": [
        "m2"
      ],
      "why_requires": "The goal is to unify @memoize and @cache. Since m1 and m2 established the target API for @memoize (.memory, .invalidate_all, .invalidate, .skip), m3 must modify @cache to adopt this same API. The code_links show cache uses wraps and has its own internal cache dict, so adding these methods requires changes to the cache wrapper, building on the pattern set by the previous milestones."
    }
  ],
  "expected_causes": [
    "Implementer might forget to add .invalidate to memoize, only adding .invalidate_all.",
    "Implementer might not correctly handle the key generation for .invalidate in cache vs memoize (cache uses key_func, memoize uses default or provided key_func).",
    "Implementer might confuse .skip behavior: memoize already has it, cache does not. Unifying might require adding .skip to cache or removing it from memoize if 'unify' means making them identical. Given R1 says 'both have ... now', it implies adding missing parts to both to make them have the same set."
  ],
  "verifier_plan": "Test m1: Decorate a function with @memoize, call it, check .memory has entry. Call .invalidate_all(), check .memory is empty. Test m2: Decorate with @memoize, raise memoize.skip(42), check return is 42 and not cached. Add .invalidate(key) and test removal. Test m3: Decorate with @cache(timeout=10), check it has .invalidate(key) and .skip (if added) or consistent API. Ensure .invalidate works for cache's timeout-based cache."
}
